// Shape of /token-library.json, generated by vite-plugins/token-library.ts
// from the contents of public/Token_Library.

export interface TokenLibraryToken {
    /** Display name (file name without extension) */
    name: string
    /** URL the image is served from, relative to the app base */
    url: string
}

export interface TokenLibraryFolder {
    /** Folder name ("" for the library root) */
    name: string
    /** Path segments from the library root, e.g. ["Fey", "Nymphs"] */
    path: string[]
    folders: TokenLibraryFolder[]
    tokens: TokenLibraryToken[]
    /** Total number of tokens in this folder and all subfolders */
    totalTokens: number
}
